export const BLOB_NAMES = Object.keys(BLOB_PATHS)

/** Pick a shape deterministically, so a given card always gets the same one. */
export function blobShape(index, role = 'card') {
  const pool = BLOB_NAMES.filter((n) => n.startsWith(role))
  const names = pool.length ? pool : BLOB_NAMES
  return names[((index % names.length) + names.length) % names.length]
}

/** Style object clipping an element to one of the shapes. */
export function blobClip(name) {
  return { clipPath: `url(#jni-blob-${name})` }
}

/** Mount once. Renders the clipPath defs every blobClip() refers to. */
export function BlobClipDefs() {
  return (
    <svg width="0" height="0" aria-hidden="true"
      style={{ position: 'absolute', width: 0, height: 0, overflow: 'hidden' }}>
      <defs>
        {BLOB_NAMES.map((name) => (
          <clipPath key={name} id={`jni-blob-${name}`} clipPathUnits="objectBoundingBox">
            <path d={BLOB_PATHS[name]} />
          </clipPath>
        ))}
      </defs>
    </svg>
  )
}
